mapper.select:
SELECT
    id, user_id, interest_type, interest_key, interest_score,
    behavior_count, update_time, create_time
FROM user_interest_tag
WHERE user_id = #{userId}
  AND interest_type = #{interestType}
  AND interest_key = #{interestKey}
LIMIT 1

SELECT
    id, user_id, interest_type, interest_key, interest_score,
    behavior_count, update_time, create_time
FROM user_interest_tag
WHERE user_id = #{userId}
  AND interest_type = #{interestType}
  AND interest_score > 0.1
ORDER BY interest_score DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM user_interest_tag
WHERE user_id = #{userId}
  AND interest_score < #{minScore}
